void main() {
  // A map links keys to values: {key: value}.
  Map<String, double> menu = {'coffee': 1.40, 'tea': 1.20, 'toast': 2.10};
  print('A coffee costs ${menu['coffee']} euros');

  // map[key] = value changes a value or adds a new key.
  menu['tea'] = 1.30;
  menu['juice'] = 2.50;
  print(menu);

  // A missing key gives null; ?? puts a default in its place.
  print('Cake: ${menu['cake']}, or rather ${menu['cake'] ?? 0.0}');

  // remove deletes a key with its value.
  menu.remove('toast');
  print('Toast? ${menu.containsKey('toast')}. Keys: ${menu.keys.toList()}');

  // entries gives each key together with its value.
  for (var item in menu.entries) {
    print('${item.key.padRight(8)}${item.value.toStringAsFixed(2)}');
  }

  // Counting with a map: one key per drink.
  var orders = ['coffee', 'tea', 'coffee', 'juice', 'coffee', 'tea'];
  var counts = <String, int>{};
  for (var drink in orders) {
    counts[drink] = (counts[drink] ?? 0) + 1;
  }
  print('Orders: $counts');
  print('Different drinks: ${counts.length}');
}

// A function: return type, name, parameters and a block.
double toFahrenheit(double celsius) {
  return celsius * 9 / 5 + 32;
}

// Arrow syntax (=>) for a function that is a single expression.
bool isFreezing(double celsius) => celsius <= 0;

String describe(double celsius) =>
    isFreezing(celsius) ? 'freezing' : (celsius > 30 ? 'hot' : 'mild');

// void: the function does something but returns nothing.
void report(String city, double celsius) {
  String f = toFahrenheit(celsius).toStringAsFixed(1);
  print('${city.padRight(8)}$celsius C = $f F, ${describe(celsius)}');
}

void main() {
  report('Oslo', -4);
  report('Madrid', 21);
  report('Seville', 36.5);

  // The result can be kept in a variable or used directly.
  double boiling = toFahrenheit(100);
  print('Water boils at $boiling F');
  print('Freezing at 0 C? ${isFreezing(0)}');

  // Functions are values too: they can go in a variable.
  var convert = toFahrenheit;
  var square = (int n) => n * n;
  print('Body: ${convert(37).toStringAsFixed(1)} F, 12 squared: ${square(12)}');
}

// Optional positional parameters go in [ ], with a default value.
String greet(String name, [String greeting = 'Hello']) => '$greeting, $name!';

// Named parameters go in { }; required makes one compulsory.
void book(String hotel, {required int nights, int guests = 2, bool breakfast = false}) {
  int cost = nights * guests * 45;
  if (breakfast) cost += nights * guests * 8;
  String extra = breakfast ? ' with breakfast' : '';
  print('$hotel: $nights nights, $guests guests$extra = $cost euros');
}

// Named parameters with defaults make long calls easy to read.
String button(String text, {String colour = 'blue', bool rounded = true}) =>
    '[$text] $colour${rounded ? ', rounded' : ''}';

void main() {
  print(greet('Marta'));
  print(greet('Marta', 'Good morning'));

  // Named arguments carry their name and can go in any order.
  book('Hotel Sol', nights: 3);
  book('Hotel Mar', guests: 3, nights: 2);
  book('Casa Rural', nights: 4, breakfast: true, guests: 4);
  // book('Hotel Sol');  // Error: nights is required.

  print(button('Buy'));
  print(button('Cancel', colour: 'grey', rounded: false));
}

// A ? after the type means it may hold null: "no value".
String? findEmail(Map<String, String> book, String name) => book[name];

void main() {
  var emails = {'Ana': 'ana@mail.com', 'Luis': 'luis@work.org'};

  // String can never be null; String? can, and starts as null.
  String owner = 'Ana';
  String? nickname;
  print('Owner: $owner, nickname: $nickname');

  // ?? gives a default value when the left side is null.
  print('Nickname: ${nickname ?? 'none'}');

  // ?. calls the method only if the value is not null.
  String? marta = findEmail(emails, 'Marta');
  print('Marta: ${marta?.toUpperCase()}');
  print('Marta: ${marta?.length ?? 0} characters');

  // After checking != null, Dart treats it as a plain String.
  String? ana = findEmail(emails, 'Ana');
  if (ana != null) {
    print('Ana writes from ${ana.split('@')[1]}');
  }

  // ! means "I am sure it is not null" (and fails if it is).
  String luis = emails['Luis']!;
  print('Luis: ${luis.length} characters');

  // ??= gives a value only if the variable is still null.
  nickname ??= 'Nana';
  nickname ??= 'Other';
  print('Nickname now: $nickname');
}

void main() {
  String raw = '   Dart is fun and Dart is fast   ';

  // trim removes the spaces at both ends.
  String text = raw.trim();
  print('[$text]');

  // Changing case and looking for text.
  print(text.toUpperCase());
  print('Has "fast"? ${text.contains('fast')}');
  print('Starts with "Dart"? ${text.startsWith('Dart')}');
  print('"is" first at ${text.indexOf('is')}, last at ${text.lastIndexOf('is')}');

  // replaceAll swaps text; substring(start, end) cuts a piece.
  print(text.replaceAll('Dart', 'Flutter'));
  print('Characters 0 to 4: ${text.substring(0, 4)}');

  // split cuts the text into a list; join glues it back.
  var words = text.split(' ');
  print('${words.length} words: $words');
  print(words.join('_'));

  // padRight and padLeft fill with characters to line up columns.
  var items = ['tea', 'croissant', 'juice'];
  var prices = ['1.30', '2.25', '12.50'];
  for (int i = 0; i < items.length; i++) {
    print('${items[i].padRight(12, '.')}${prices[i].padLeft(6)}');
  }

  // Strings never change: each method returns a new one.
  print('raw still has ${raw.length} characters');
}

void main() {
  var names = ['Ana', 'Ben', 'Carla'];
  var orders = [24.0, 8.5, 61.0, 15.25, 42.0, 5.0];

  // forEach runs a function with each element.
  names.forEach((name) => print('Welcome, $name'));

  // map turns each element into another; toList makes a list.
  var labels = orders.map((o) => '${o.toStringAsFixed(2)} EUR').toList();
  print('Labels: $labels');

  // where keeps only the elements that meet the condition.
  var big = orders.where((o) => o >= 20).toList();
  print('Orders of 20 or more: $big');

  // reduce combines the elements two by two into one.
  var total = orders.reduce((a, b) => a + b);
  var highest = orders.reduce((a, b) => a > b ? a : b);
  print('Total: $total, highest: $highest');

  // fold is like reduce, but starts from a value of any type.
  var small = orders.fold(0, (count, o) => o < 10 ? count + 1 : count);
  var initials = names.fold('', (text, name) => text + name[0]);
  print('Small orders: $small, initials: $initials');

  // They chain: filter, transform and add up in one go.
  var points = orders
      .where((o) => o > 10)
      .map((o) => o ~/ 10)
      .fold(0, (sum, p) => sum + p);
  print('Loyalty points: $points');
}

// throw raises an error when something is not allowed.
double withdraw(double balance, double amount) {
  if (amount <= 0) throw ArgumentError('the amount must be positive');
  if (amount > balance) throw StateError('not enough money');
  return balance - amount;
}

void main() {
  // int.parse fails with a FormatException on bad text.
  for (var text in ['42', 'forty']) {
    try {
      print('Read: ${int.parse(text)}');
    } on FormatException {
      print('"$text" is not a number');
    }
  }

  // on catches one type of error; catch (e) gives the error itself.
  double balance = 100;
  for (var amount in [30.0, -5.0, 500.0]) {
    try {
      balance = withdraw(balance, amount);
      print('Took out $amount, balance $balance');
    } on ArgumentError catch (e) {
      print('Refused: ${e.message}');
    } catch (e) {
      print('Error: $e');
    } finally {
      // finally always runs, with or without an error.
      print('  operation of $amount checked');
    }
  }
  print('Final balance: $balance');
}

import 'dart:io';

void main() {
  // A File is a path: here, a file in the current folder.
  var file = File('shopping.txt');

  // writeAsStringSync creates the file, or replaces what it had.
  file.writeAsStringSync('bread,2\nmilk,1\n');

  // With FileMode.append it adds at the end instead.
  file.writeAsStringSync('eggs,12\napples,6\n', mode: FileMode.append);
  print('Exists? ${file.existsSync()}. Size: ${file.lengthSync()} bytes');

  // readAsStringSync gives the whole text at once.
  print(file.readAsStringSync().trim());

  // readAsLinesSync gives a list with one string per line.
  var lines = file.readAsLinesSync();
  int units = 0;
  for (var line in lines) {
    units += int.parse(line.split(',')[1]);
  }
  print('${lines.length} products, $units units in total');

  // Reading a file that does not exist throws an exception.
  try {
    File('missing.txt').readAsStringSync();
  } on FileSystemException catch (e) {
    print('Could not open ${e.path}');
  }

  // existsSync lets us check before reading.
  print('Is there a missing.txt? ${File('missing.txt').existsSync()}');
}

const prices = {'bread': 1.20, 'milk': 0.95, 'cheese': 4.50, 'apples': 2.30};

// Gives the cost of one "product,units" line, or throws an error.
double lineCost(String line) {
  var parts = line.split(',');
  double? price = prices[parts[0]];
  int? units = int.tryParse(parts[1]);
  if (price == null) throw ArgumentError('${parts[0]} is not sold here');
  if (units == null || units <= 0) throw ArgumentError('bad quantity in "$line"');
  return price * units;
}

String row(String label, double euros) =>
    label.padRight(14) + euros.toStringAsFixed(2).padLeft(7);

void main() {
  var cart = ['bread,2', 'cheese,1', 'milk,x', 'apples,3', 'ham,1', 'milk,4', 'bread,0'];
  var totals = <String, double>{};
  for (var line in cart) {
    var product = line.split(',')[0];
    try {
      totals[product] = (totals[product] ?? 0) + lineCost(line);
    } on ArgumentError catch (e) {
      print('Skipped: ${e.message}');
    }
  }
  totals.forEach((product, cost) => print(row(product, cost)));
  double subtotal = totals.values.fold(0, (a, b) => a + b);
  double rate = switch (subtotal) { >= 20 => 0.10, >= 10 => 0.05, _ => 0.0 };
  print('-' * 21);
  print(row('Subtotal', subtotal));
  print(row('Discount (${(rate * 100).round()}%)', -subtotal * rate));
  print(row('TOTAL', subtotal * (1 - rate)));
}

