// A record type with named fields, given a short name.
typedef Reading = ({String city, double celsius});

// Returning a positional record: three values, no helper class.
(double, double, double) summarize(List<double> values) {
  final sorted = [...values]..sort();
  final average = values.reduce((a, b) => a + b) / values.length;
  return (sorted.first, sorted.last, average);
}

void main() {
  final List<Reading> readings = [
    (city: 'Madrid', celsius: 31.5),
    (city: 'Bilbao', celsius: 22.0),
    (city: 'Seville', celsius: 36.2),
    (city: 'Vigo', celsius: 19.8),
  ];
  // Destructure the result into three variables at once.
  final (low, high, avg) = summarize([for (final r in readings) r.celsius]);
  print('Low $low, high $high, average ${avg.toStringAsFixed(1)}');

  // :city is short for city: city (take the field into a variable).
  for (final (:city, :celsius) in readings) {
    if (celsius > 30) print('Heat warning in $city ($celsius C)');
  }

  final first = readings.first;
  print('Fields: ${first.city}, positional: ${summarize([1, 2]).$2}');
  print('Equal by value: ${(city: 'Vigo', celsius: 19.8) == readings[3]}');

  var (a, b) = ('left', 'right');
  (a, b) = (b, a); // swap without a temporary variable
  print('Swapped: $a $b');
}

// sealed: every subtype is declared in this file, so the compiler
// knows the complete list and can check that a switch covers it.
sealed class LoadState {}

class Loading extends LoadState {}
class Loaded extends LoadState {
  final List<String> items;
  Loaded(this.items);
}
class Failed extends LoadState {
  final int code;
  final String message;
  Failed(this.code, this.message);
}

// Exhaustive switch: no default needed; forget a case and it won't compile.
String render(LoadState state) => switch (state) {
      Loading() => 'Showing spinner...',
      Loaded(items: []) => 'Nothing here yet',
      Loaded(:final items) when items.length == 1 => 'One item: ${items[0]}',
      Loaded(:final items) => '${items.length} items: ${items.join(', ')}',
      Failed(code: 401) => 'Session expired, please log in',
      Failed(:final code, :final message) => 'Error $code: $message',
    };

void main() {
  final states = [Loading(), Loaded([]), Loaded(['Milk']), Loaded(['Tea', 'Rice']),
      Failed(401, 'Unauthorized'), Failed(503, 'Server busy')];
  for (final state in states) print(render(state));

  // Patterns also check and unpack a map, such as decoded JSON.
  final Object json = {'user': 'carmen', 'roles': ['admin', 'editor']};
  if (json case {'user': String name, 'roles': [String role, ...]}) print('$name is $role');
}

class Money implements Comparable<Money> {
  final int cents;
  final String currency;
  const Money(this.cents, [this.currency = 'EUR']);

  Money operator +(Money other) {
    if (other.currency != currency) throw ArgumentError('$currency + ${other.currency}');
    return Money(cents + other.cents, currency);
  }
  Money operator *(int times) => Money(cents * times, currency);
  bool operator <(Money other) => cents < other.cents;

  @override
  int compareTo(Money other) => cents.compareTo(other.cents); // for sort()

  // Equal by value: same amount and currency. hashCode must agree with ==.
  @override
  bool operator ==(Object other) =>
      other is Money && other.cents == cents && other.currency == currency;
  @override
  int get hashCode => Object.hash(cents, currency);

  @override
  String toString() => '${(cents / 100).toStringAsFixed(2)} $currency';
}

void main() {
  final coffee = Money(150), croissant = Money(195);
  print('Order: ${coffee * 2 + croissant}, cheaper: ${coffee < croissant}');
  print('== ${Money(150) == coffee}, identical ${identical(Money(150), coffee)}');
  print('Distinct prices: ${{coffee, Money(150), croissant}}'); // a Set
  print('Sorted: ${[Money(999), coffee, croissant]..sort()}');
  try { coffee + Money(150, 'USD'); } on ArgumentError catch (e) { print('Cannot add ${e.message}'); }
}

